CREATE TABLE schema_migrations (version VARCHAR(64) NOT NULL PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE api_nonces (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, key_id VARCHAR(128) NOT NULL, nonce VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_nonce_key (key_id,nonce), KEY idx_nonce_expiry (expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE commands (command_id VARCHAR(80) NOT NULL PRIMARY KEY, idempotency_key VARCHAR(255) NOT NULL, command_type VARCHAR(80) NOT NULL, actor VARCHAR(255) NOT NULL, authority_context JSON NOT NULL, request_fingerprint CHAR(64) NOT NULL, result_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_command_idempotency (idempotency_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE communications (communication_id VARCHAR(80) NOT NULL PRIMARY KEY, applicant_id VARCHAR(255) NULL, message_type VARCHAR(120) NOT NULL, canonical_recipient VARCHAR(320) NULL, canonical_subject TEXT NULL, canonical_body MEDIUMTEXT NULL, authority_snapshot JSON NOT NULL, status VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_communications_applicant (applicant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE previews (preview_id VARCHAR(80) NOT NULL PRIMARY KEY, communication_id VARCHAR(80) NULL, applicant_id VARCHAR(255) NOT NULL, snapshot_identity VARCHAR(255) NOT NULL, message_type VARCHAR(120) NOT NULL, canonical_recipient VARCHAR(320) NOT NULL, canonical_subject TEXT NOT NULL, canonical_body MEDIUMTEXT NOT NULL, cc_list TEXT NULL, bcc_list TEXT NULL, portal_hydration JSON NULL, payload_fingerprint CHAR(64) NOT NULL, authority_snapshot JSON NOT NULL, status VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_preview_id (preview_id), KEY idx_previews_applicant (applicant_id), CONSTRAINT fk_preview_communication FOREIGN KEY (communication_id) REFERENCES communications(communication_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE operations (operation_id VARCHAR(80) NOT NULL PRIMARY KEY, preview_id VARCHAR(80) NULL, communication_id VARCHAR(80) NOT NULL, applicant_id VARCHAR(255) NULL, idempotency_key VARCHAR(255) NOT NULL, authority_context JSON NOT NULL, status VARCHAR(64) NOT NULL, started_at DATETIME NULL, completed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_operation_idempotency (idempotency_key), KEY idx_operations_applicant (applicant_id), KEY idx_operations_lookup (communication_id,status), CONSTRAINT fk_operation_preview FOREIGN KEY (preview_id) REFERENCES previews(preview_id), CONSTRAINT fk_operation_communication FOREIGN KEY (communication_id) REFERENCES communications(communication_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE receipts (receipt_id VARCHAR(80) NOT NULL PRIMARY KEY, operation_id VARCHAR(80) NOT NULL, communication_id VARCHAR(80) NOT NULL, result VARCHAR(80) NOT NULL, block_code VARCHAR(120) NULL, block_reason TEXT NULL, technical_timestamp DATETIME NOT NULL, provider VARCHAR(120) NULL, provider_message_id VARCHAR(255) NULL, provider_thread_id VARCHAR(255) NULL, rfc_message_id VARCHAR(255) NULL, metadata JSON NULL, migration_source VARCHAR(120) NULL, uncertainty_state VARCHAR(80) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_receipt_id (receipt_id), KEY idx_receipt_operation (operation_id), KEY idx_receipt_provider_message (provider_message_id), CONSTRAINT fk_receipt_operation FOREIGN KEY (operation_id) REFERENCES operations(operation_id), CONSTRAINT fk_receipt_communication FOREIGN KEY (communication_id) REFERENCES communications(communication_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE communication_events (event_id VARCHAR(80) NOT NULL PRIMARY KEY, communication_id VARCHAR(80) NULL, operation_id VARCHAR(80) NULL, receipt_id VARCHAR(80) NULL, event_type VARCHAR(80) NOT NULL, event_source VARCHAR(120) NOT NULL, confidence VARCHAR(32) NOT NULL, metadata JSON NULL, event_timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_event_id (event_id), KEY idx_event_timestamp (event_timestamp), KEY idx_event_type (event_type), KEY idx_event_operation (operation_id), CONSTRAINT fk_event_communication FOREIGN KEY (communication_id) REFERENCES communications(communication_id), CONSTRAINT fk_event_operation FOREIGN KEY (operation_id) REFERENCES operations(operation_id), CONSTRAINT fk_event_receipt FOREIGN KEY (receipt_id) REFERENCES receipts(receipt_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cohorts (cohort_id VARCHAR(80) NOT NULL PRIMARY KEY, cohort_fingerprint CHAR(64) NOT NULL, population_snapshot JSON NOT NULL, message_type VARCHAR(120) NOT NULL, actor VARCHAR(255) NOT NULL, execution_policy JSON NOT NULL, status VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_cohort_fingerprint (cohort_fingerprint), KEY idx_cohort_status (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cohort_recipients (cohort_id VARCHAR(80) NOT NULL, applicant_id VARCHAR(255) NOT NULL, communication_id VARCHAR(80) NULL, preview_id VARCHAR(80) NULL, operation_id VARCHAR(80) NULL, receipt_id VARCHAR(80) NULL, ordinal_no INT UNSIGNED NOT NULL, eligibility_state VARCHAR(64) NOT NULL, execution_state VARCHAR(64) NOT NULL, retry_state VARCHAR(64) NOT NULL, block_reason TEXT NULL, canonical_payload JSON NOT NULL, PRIMARY KEY (cohort_id,applicant_id), UNIQUE KEY uq_cohort_ordinal (cohort_id,ordinal_no), KEY idx_cohort_recipient_cohort (cohort_id), KEY idx_cohort_recipient_applicant (applicant_id), CONSTRAINT fk_cr_cohort FOREIGN KEY (cohort_id) REFERENCES cohorts(cohort_id), CONSTRAINT fk_cr_communication FOREIGN KEY (communication_id) REFERENCES communications(communication_id), CONSTRAINT fk_cr_preview FOREIGN KEY (preview_id) REFERENCES previews(preview_id), CONSTRAINT fk_cr_operation FOREIGN KEY (operation_id) REFERENCES operations(operation_id), CONSTRAINT fk_cr_receipt FOREIGN KEY (receipt_id) REFERENCES receipts(receipt_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
